INSERT INTO changelog_cambios (fecha, titulo, descripcion, categoria) VALUES
  (CURRENT_DATE, 'Diseño unificado en Venta Rápida, Visita Técnica y todo el sistema', 'Venta Rápida, Visita Técnica y Visitas de Relevamiento de Datos habían quedado desalineadas del resto del sistema al no tener el atributo data-section — perdían el tinte de color y la franja de acento de cada sección de forma silenciosa. Corregido en esas y otras 4 páginas, más una sección ''venta-rapida'' que faltaba en el CSS. Se unificó el estilo de card (border-gray-400 + shadow-lg) y el ancho máximo de página (1440px) en todo el sistema, se sacó un componente compartido para el encabezado de formularios y otro para las cards de sección, y se corrigieron varios bugs reales de mobile: el botón de borrar foto que dependía de :hover (inalcanzable en celular), la firma digital que se guardaba deformada por un problema de proporciones del canvas, checkboxes y botones táctiles muy chicos, grillas que no se adaptaban a 375px y dos scrolls anidados en Venta Rápida.', 'fix');
INSERT INTO schema_migrations (filename) VALUES ('20260831000001_changelog_diseno_unificado_en_venta_rapida_visita_.sql') ON CONFLICT DO NOTHING;
